it.each([
  ['full', 'source.js', false],
  ['hotfix', 'source.js', false],
  ['tweak', 'source.js', false],
  ['tweak', 'docs/openspec/changes/example/proposal.md', false],
  ['full', 'docs/superpowers/plans/example-plan.md', false],
  ['full', 'docs/superpowers/specs/example-design.md', false],
  ['tweak', 'docs/openspec/changes/example/proposal.md', true],
  ['full', 'docs/superpowers/plans/example-plan.md', true],
] as const)(
  'runs actual %s domain checks with %s and archive recovery=%s',
  async (profile, artifactRef, recover) => {
    const f = await fixture(profile, ['review'], undefined, undefined, [artifactRef]);
    await f.reachReview();
    expect(f.run.state).toMatchObject({ phase: 'build' });
    await expect(f.work({ verdict: 'pass' })).rejects.toMatchObject({ code: 'OUTCOME_REJECTED' });
    f.runtime = f.runtimeFactory();
    await f.refresh();
    expect(f.run.actions.at(-1)).toMatchObject({
      stepId: 'classic.extension.review',
      status: 'running',
    });
    const action = f.run.actions.at(-1)!;
    f.run = await f.runtime.recordOutcome({
      runId: 'example',
      outcome: {
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        claimToken: action.claim!.token,
        outcomeId: 'real-review',
        status: 'succeeded',
        output: await f.reviewOutput(),
      },
      context: { requestId: 'review', projectRoot: f.projectRoot },
    });
    expect(f.run.state).toMatchObject({ phase: 'verify' });
    const reportRef = 'docs/superpowers/reports/example-verify.md';
    await fs.writeFile(path.join(f.projectRoot, reportRef), '# Verification\nPASS\n');
    await f.work({ event: 'verification-ready', verificationReport: reportRef });
    await f.evidence();
    f.run = await f.runtime.execute({
      runId: 'example',
      actionId: f.run.actions.find((action) => action.status === 'pending')!.id,
      executorId: 'comet-classic-check',
      context: { requestId: 'public-verify-check', projectRoot: f.projectRoot },
    });
    await f.evidence();
    await f.work({ targetBranch: 'main', summary: 'Archive the checked change' });
    await f.approve('local');
    f.run = await f.runtime.execute({
      runId: 'example',
      actionId: f.run.actions.find((action) => action.status === 'pending')!.id,
      executorId: 'comet-classic-archive-preflight',
      context: { requestId: 'public-archive-preflight', projectRoot: f.projectRoot },
    });
    if (recover) {
      const action = f.run.actions.find((entry) => entry.status === 'pending')!;
      f.run = await f.runtime.claim({
        runId: 'example',
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'comet-classic-archive',
        claimToken: 'lost-archive',
        expectedRevision: f.run.revision,
        context: { requestId: 'claim-archive', projectRoot: f.projectRoot },
      });
      const claimed = f.run.actions.find((entry) => entry.id === action.id)!;
      const result = await classic.runClassicSdkArchive(f.run, claimed, f.projectRoot);
      const archiveDirectory = (result.output as { archiveDirectory: string }).archiveDirectory;
      const archivedArtifact = path.join(
        f.projectRoot,
        artifactRef.replace('docs/openspec/changes/example/', `${archiveDirectory}/`),
      );
      const acceptedArtifact = await fs.readFile(archivedArtifact, 'utf8');
      f.run = await f.runtime.markUnknown({
        runId: 'example',
        actionId: action.id,
        attempt: action.attempt,
        reason: 'Archive finished but result was lost',
      });
      f.runtime = f.runtimeFactory();
      await f.refresh();
      await fs.writeFile(archivedArtifact, `${acceptedArtifact}\nUnaccepted content\n`);
      await expect(
        classic.recoverClassicSdkArchive(f.runtime, {
          runId: 'example',
          projectRoot: f.projectRoot,
        }),
      ).rejects.toThrow(/Classic/);
      await fs.writeFile(archivedArtifact, acceptedArtifact);
      if (profile === 'full') {
        const receiptFile = path.join(
          f.projectRoot,
          archiveDirectory,
          '.comet/archive-documents.json',
        );
        const originalReceipt = await fs.readFile(receiptFile, 'utf8');
        const forged = JSON.parse(originalReceipt);
        forged.documents[artifactRef].original += '\nForged preimage\n';
        await fs.writeFile(receiptFile, JSON.stringify(forged));
        await expect(
          classic.recoverClassicSdkArchive(f.runtime, {
            runId: 'example',
            projectRoot: f.projectRoot,
          }),
        ).rejects.toThrow(/Classic/);
        await fs.writeFile(receiptFile, originalReceipt);
      }
      f.run = await classic.recoverClassicSdkArchive(f.runtime, {
        runId: 'example',
        projectRoot: f.projectRoot,
      });
      f.runtime = f.runtimeFactory();
      expect(
        (
          await classic.recoverClassicSdkArchive(f.runtime, {
            runId: 'example',
            projectRoot: f.projectRoot,
          })
        ).revision,
      ).toBe(f.run.revision);
    } else {
      f.run = await f.runtime.execute({
        runId: 'example',
        actionId: f.run.actions.find((action) => action.status === 'pending')!.id,
        executorId: 'comet-classic-archive',
        context: { requestId: 'public-archive', projectRoot: f.projectRoot },
      });
    }
    expect(f.run.state).toMatchObject({ archived: true });
    expect(await f.openSpec.invocations()).toEqual([
      {
        args: ['archive', 'example', '--yes'],
        cwd: await fs.realpath(path.join(f.projectRoot, 'docs')),
      },
    ]);
    const archiveRef = (
      f.run.actions.findLast((action) => action.stepId.endsWith('.archive.execute'))!.outcome!
        .output as { archiveDirectory: string }
    ).archiveDirectory;
    const paths = [
      'docs/openspec/changes/example',
      archiveRef,
      reportRef,
      ...(profile === 'full'
        ? ['docs/superpowers/specs/example-design.md', 'docs/superpowers/plans/example-plan.md']
        : []),
    ];
    git(f.projectRoot, ['add', '--', ...paths]);
    git(f.projectRoot, ['commit', '-m', 'chore: archive example']);
    await f.work({
      action: 'local',
      targetBranch: 'main',
      commit: git(f.projectRoot, ['rev-parse', 'HEAD']),
    });
    expect(f.run.status).toBe('completed');

    await expect(inspectClassicSdkRun(f.projectRoot, 'example')).rejects.toThrow();
    const file = path.join(f.projectRoot, archiveRef, 'comet-state.yaml');
    expect(await fs.readFile(file, 'utf8')).toContain('application_checkpoint:');
    await expect(createClassicSdkStateStore(f.projectRoot).read('example')).rejects.toThrow(
      /original fixed Application/,
    );
  },
  90000,
);

it('already excludes untracked ignored outputs in the public default check surface', async () => {
  await prepare('compat');
  await put('.gitignore', '.vite/\ncoverage/\nbin/\nobj/\n');
  const script = `for (const dir of ['.vite', 'coverage', 'bin', 'obj']) { require('fs').mkdirSync(dir, { recursive: true }); require('fs').writeFileSync(dir + '/result', 'generated'); }`;
  const result = await invoke(
    'check',
    'run',
    'demo',
    'build',
    '--',
    process.execPath,
    '-e',
    script,
  );
  expect(result.exitCode, result.stdout).toBe(0);
  expect(result.response.data.inputBefore).toBe(result.response.data.inputAfter);
});

it('reports undeclared output drift and accepts only explicitly selected output presets', async () => {
  await prepare('compat');
  const argv = [
    process.execPath,
    '-e',
    `require('fs').mkdirSync('.vite', { recursive: true }); require('fs').writeFileSync('.vite/result', String(Date.now()));`,
  ];
  const failed = await invoke('check', 'run', 'demo', 'build', '--', ...argv);
  expect(failed.exitCode, failed.stdout).toBe(1);
  expect(failed.response.stderr).toContain('.vite/result');
  await policy({ argv, presets: ['vite'] });
  const passed = await invoke('check', 'run', 'demo', 'build', '--', ...argv);
  expect(passed.exitCode, passed.stdout).toBe(0);
  expect(passed.response.data.inputBefore).toBe(passed.response.data.inputAfter);
});

it('expands output presets canonically without dropping source or dependency inputs', async () => {
  await policy({ presets: ['vite', 'coverage', 'dotnet'] });
  const first = await snapshot();
  for (const output of [
    '.vite/cache',
    'packages/ui/.vite/cache',
    'coverage/report',
    'packages/api/bin/app',
    'packages/api/obj/app',
    '.nyc_output/data',
  ])
    await put(output, 'output');
  expect((await snapshot()).digest).toBe(first.digest);
  const declaration = await readCheckPolicy(root, identity);
  await policy({ outputs: declaration.outputs, presets: ['dotnet', 'vite', 'coverage', 'vite'] });
  expect((await snapshot()).digest).toBe(first.digest);
  await put('src/source.ts', 'source');
  const source = await snapshot();
  expect(source.digest).not.toBe(first.digest);
  await put('node_modules/.modules.yaml', 'dependencies');
  expect((await snapshot()).digest).not.toBe(source.digest);
});

it.each([{ presets: ['unknown'] }, { presets: 'vite' }, { presets: [false] }])(
  'rejects invalid presets %j',
  async ({ presets }) => {
    await policy({ presets });
    await expect(snapshot()).rejects.toThrow(/preset/iu);
  },
);

it('does not ignore tracked inputs just because a gitignore rule matches', async () => {
  await put('.gitignore', 'generated/\n');
  await put('generated/input.json', 'one');
  execFileSync('git', ['add', '-f', 'generated/input.json'], { cwd: root });
  const first = await snapshot();
  expect(first.entries.map((entry) => entry.p)).toContain('generated/input.json');
  await put('generated/input.json', 'two');
  expect((await snapshot()).digest).not.toBe(first.digest);
});

it('includes ignored directory inputs and node_modules inputs when explicitly declared', async () => {
  await put('.gitignore', 'fixtures/\nnode_modules/\n');
  await put('fixtures/input.json', 'one');
  await put('node_modules/local-fixture/value.json', 'one');
  await policy({ files: ['fixtures', 'node_modules/local-fixture/**'] });
  const first = await snapshot();
  expect(first.entries.map((entry) => entry.p)).toEqual(
    expect.arrayContaining(['fixtures/input.json', 'node_modules/local-fixture/value.json']),
  );
  await put('fixtures/next.json', 'new');
  expect((await snapshot()).digest).not.toBe(first.digest);
});

it('keeps explicitly selected output directories neutral outside Git too', async () => {
  await fs.rm(path.join(root, '.git'), { recursive: true, force: true });
  await policy({ presets: ['vite', 'coverage', 'dotnet'] });
  const first = await snapshot();
  await put('.vite/result', 'cache');
  await put('bin/result', 'output');
  await put('coverage/result', 'report');
  expect((await snapshot()).digest).toBe(first.digest);
});

it('does not treat source files named bin or coverage as preset output directories', async () => {
  await policy({ presets: ['dotnet', 'coverage'] });
  const first = await snapshot();
  await put('bin', 'source script');
  await put('coverage', 'source script');
  const next = await snapshot();
  expect(next.digest).not.toBe(first.digest);
  expect(next.entries.map((entry) => entry.p)).toEqual(expect.arrayContaining(['bin', 'coverage']));
});

it('still binds policy file bytes when the command declares the policy itself as input', async () => {
  await policy({ files: ['.comet/check-policy.json'], presets: ['vite'] });
  const first = await snapshot();
  expect(first.entries.map((entry) => entry.p)).toContain('.comet/check-policy.json');
  await fs.appendFile(path.join(root, '.comet/check-policy.json'), '\n');
  expect((await snapshot()).digest).not.toBe(first.digest);
});

it('keeps new intermediate directories containing only declared outputs neutral outside Git', async () => {
  await fs.rm(path.join(root, '.git'), { recursive: true, force: true });
  await policy({ presets: ['vite', 'coverage', 'dotnet'] });
  const first = await snapshot();
  await put('packages/new-app/.vite/result', 'cache');
  await put('packages/new-service/obj/result', 'output');
  const outputs = await snapshot();
  expect(outputs.digest).toBe(first.digest);
  await put('packages/new-app/source.ts', 'real input');
  expect((await snapshot()).digest).not.toBe(first.digest);
});

it('hashes 1000 short paths in one bounded process and preserves order', () => {
    const names = Array.from({ length: 1000 }, (_, index) => `source-${index}.ts`);
    expect([...hashGitPaths('/project', names)]).toEqual(names.map((name) => [name, digest(name)]));
    expect(batches()).toHaveLength(1);
  });

it('bounds arguments with non-ASCII, spaces, quotes and backslashes without rewriting paths', () => {
    const root = 'C:\\working directory\\项目';
    const names = Array.from({ length: 200 }, (_, index) => `${'目录 '.repeat(30)}${index} \\".ts`);
    expect([...hashGitPaths(root, names).keys()]).toEqual(names);
    expect(batches()).toHaveLength(1);
    for (const [, args, options] of vi.mocked(spawnSync).mock.calls) {
      const argumentList = args as string[];
      const quotedUpperBound = argumentList.reduce(
        (total, argument) => total + Buffer.byteLength(argument, 'utf8') * 2 + 3,
        0,
      );
      expect(quotedUpperBound).toBeLessThanOrEqual(16 * 1024);
      expect(options).not.toHaveProperty('shell', true);
      expect(Buffer.byteLength(options!.input as string)).toBeLessThanOrEqual(256 * 1024);
      expect(argumentList).toContain('--stdin-paths');
    }
  });

it('isolates an over-budget path so it cannot poison neighboring successful batches', () => {
    const oversized = 'x'.repeat(30_000);
    const names = ['before.ts', oversized, 'after.ts'];
    expect([...hashGitPaths('/project', names).keys()]).toEqual(['before.ts', 'after.ts']);
    expect(batches().some((batch) => batch.length === 1 && batch[0] === oversized)).toBe(true);
  });

it('retains successes outside a failed batch and recursively isolates only that failure', () => {
    const names = Array.from({ length: 800 }, (_, index) => `source-${index}.ts`);
    const inputs = [...names.slice(0, 300), 'missing', ...names.slice(300)];
    expect([...hashGitPaths('/project', inputs).keys()]).toEqual(names);
    expect(batches().length).toBeLessThanOrEqual(21);
    expect(batches().some((batch) => batch.includes(names[0]) && !batch.includes('missing'))).toBe(
      true,
    );
    expect(
      batches().some((batch) => batch.includes(names[799]) && !batch.includes('missing')),
    ).toBe(true);
  });

it('does not spawn Git for an empty path set', () => {
    expect(hashGitPaths('/project', []).size).toBe(0);
    expect(spawnSync).not.toHaveBeenCalled();
  });

it('keeps 1000 dirty inputs plus one deleted tracked input within 5 Git calls', async () => {
    const names = Array.from(
      { length: 1001 },
      (_, index) => `input-${String(index).padStart(4, '0')}.txt`,
    );
    await Promise.all(names.map((name) => fs.writeFile(path.join(root, name), 'old')));
    git('add', '.');
    git('commit', '-m', 'baseline');
    const before = await snapshot();
    await Promise.all(names.slice(1).map((name) => fs.writeFile(path.join(root, name), 'new')));
    await fs.unlink(path.join(root, names[0]));
    const { result, metrics } = await withCometRuntimeMetrics(snapshot);
    expect(metrics.gitCommands).toBeLessThanOrEqual(5);
    expect(result.digest).not.toBe(before.digest);
    expect(result.entries.find(({ p }) => p === names[0])?.h).toBe('missing');
    expect(
      result.entries.filter(({ p, h }) => p.startsWith('input-') && h.startsWith('git:')),
    ).toHaveLength(1000);
  });

it('preserves successful batches around missing paths and directories', async () => {
    const names = Array.from(
      { length: 70 },
      (_, index) => `input-${index}${index % 2 ? ' 路径 space' : ''}.txt`,
    );
    await Promise.all(names.map((name) => fs.writeFile(path.join(root, name), name)));
    await fs.mkdir(path.join(root, 'directory'));
    const paths = [...names.slice(0, 32), 'missing', 'directory', ...names.slice(32)];
    const { result, metrics } = await withCometRuntimeMetrics(async () =>
      hashGitPaths(root, paths),
    );
    expect([...result.keys()]).toEqual(names);
    const expected = execFileSync('git', ['hash-object', '--no-filters', '--', ...names], {
      cwd: root,
      encoding: 'utf8',
    })
      .trim()
      .split(/\r?\n/u);
    expect([...result.values()]).toEqual(expected);
    expect(metrics.gitCommands).toBeLessThanOrEqual(17);
  });

it('passes Unicode and option-like names through Git stdin without changing their meaning', async () => {
    const names = [
      '--option-like.ts',
      '中文 space.ts',
      ...(process.platform === 'win32'
        ? []
        : ['line\nbreak.ts', 'quote".ts', 'back\\slash.ts', 'tab\tname.ts']),
    ];
    await Promise.all(names.map((name) => fs.writeFile(path.join(root, name), name)));
    const result = hashGitPaths(root, names);
    const expected = execFileSync('git', ['hash-object', '--no-filters', '--', ...names], {
      cwd: root,
      encoding: 'utf8',
    })
      .trim()
      .split(/\r?\n/u);
    expect([...result.keys()]).toEqual(names);
    expect([...result.values()]).toEqual(expected);
  });

it('excludes output and runtime files before Git hashing', async () => {
    const identity = { argv: [process.execPath, '-e', ''], cwd: '.' };
    await fs.writeFile(
      path.join(root, '.comet', 'check-policy.json'),
      JSON.stringify({
        version: 2,
        commands: [{ ...identity, outputs: ['dist/**'] }],
      }),
    );
    await fs.writeFile(path.join(root, 'source.js'), 'source');
    git('add', '.');
    git('commit', '-m', 'baseline');
    const collect = () =>
      collectCheckSnapshot(root, change, identity, { verificationReport: null });
    const before = await withCometRuntimeMetrics(collect);
    const outputDirs = [
      path.join(root, 'dist'),
      path.join(change, '.comet', 'checks'),
      path.join(root, '.comet', 'runtime'),
    ];
    for (const directory of outputDirs) {
      await fs.mkdir(directory, { recursive: true });
      await Promise.all(
        Array.from({ length: 100 }, (_, index) =>
          fs.writeFile(path.join(directory, `${index}.log`), 'output'),
        ),
      );
    }
    const after = await withCometRuntimeMetrics(collect);
    expect(after.result.digest).toBe(before.result.digest);
    expect(after.metrics.gitCommands).toBe(before.metrics.gitCommands);
  });

it('does not trust cached stat identities after same-size edits with restored timestamps', async () => {
    const identity = { argv: [process.execPath, '-e', ''], cwd: '.' };
    await fs.writeFile(
      path.join(root, '.comet', 'check-policy.json'),
      JSON.stringify({
        version: 2,
        commands: [{ ...identity, files: ['input.txt'] }],
      }),
    );
    const file = path.join(root, 'input.txt');
    await fs.writeFile(file, 'old');
    const original = await fs.stat(file);
    const options = { verificationReport: null, contentCache: new Map<string, string>() };
    // 模拟粗粒度文件系统：所有 lstat 时间戳均保持不变，仍必须读取内容。
    const lstat = fs.lstat.bind(fs);
    const stable = await fs.lstat(file, { bigint: true });
    vi.spyOn(fs, 'lstat').mockImplementation(async (...args: Parameters<typeof fs.lstat>) => {
      const stat = await lstat(...args);
      if (String(args[0]) === file && typeof stat.size === 'bigint') {
        return Object.assign(stat, { mtimeNs: stable.mtimeNs, ctimeNs: stable.ctimeNs });
      }
      return stat;
    });
    const { lstatSync } = await vi.importActual<typeof syncFs>('node:fs');
    vi.spyOn(syncFs, 'lstatSync').mockImplementation((...args: Parameters<typeof lstatSync>) => {
      const stat = lstatSync(...args);
      if (String(args[0]) === file && typeof stat.size === 'bigint')
        return Object.assign(stat, { mtimeNs: stable.mtimeNs, ctimeNs: stable.ctimeNs });
      return stat;
    });
    const before = await collectCheckSnapshot(root, change, identity, options);
    await fs.writeFile(file, 'new');
    await fs.utimes(file, original.atime, original.mtime);
    const after = await collectCheckSnapshot(root, change, identity, {
      ...options,
      baseline: before.entries,
    });
    expect(after.digest).not.toBe(before.digest);
    expect(after.entries.find(({ p }) => p === 'input.txt')?.h).not.toBe(
      before.entries.find(({ p }) => p === 'input.txt')?.h,
    );
  });

it('limits explicit paths but binds the declaration and dependency metadata', async () => {
  await writePolicy({ version: 1, files: ['input.txt'], git: 'none' });
  const first = await snapshot();
  await fs.writeFile(path.join(root, 'unrelated.md'), 'docs');
  expect(await snapshot()).toBe(first);
  await fs.writeFile(path.join(root, 'input.txt'), 'changed');
  expect(await snapshot()).not.toBe(first);
  const second = await snapshot();
  await fs.appendFile(path.join(root, '.comet/check-policy.json'), '\n');
  expect(await snapshot()).not.toBe(second);
  const third = await snapshot();
  await fs.mkdir(path.join(root, 'node_modules'));
  await fs.writeFile(path.join(root, 'node_modules/.modules.yaml'), 'changed');
  expect(await snapshot()).not.toBe(third);
});

it('normalizes task checkboxes by default and restores sensitivity on request', async () => {
  await writePolicy({ version: 1, git: 'none', taskCheckboxes: 'ignore' });
  const file = path.join(change, 'tasks.md');
  await fs.writeFile(file, '- [ ] implement\n```md\n- [ ] example\n```\n');
  const first = await snapshot();
  await fs.writeFile(file, '- [x] implement\n```md\n- [ ] example\n```\n');
  expect(await snapshot()).toBe(first);
  await fs.writeFile(file, '- [x] implement\n```md\n- [x] example\n```\n');
  expect(await snapshot()).not.toBe(first);
  await writePolicy({ version: 1, git: 'none', taskCheckboxes: 'include' });
  await fs.writeFile(file, '- [ ] implement\n');
  const second = await snapshot();
  await fs.writeFile(file, '- [x] implement\n');
  expect(await snapshot()).not.toBe(second);
});

it('keeps working-tree content as the default input across commits and ticks', async () => {
  const gitExec = (...args: string[]) =>
    execFileSync('git', ['-C', root, ...args], { stdio: 'ignore' });
  gitExec('init');
  gitExec('config', 'user.email', 'test@example.com');
  gitExec('config', 'user.name', 'Test');
  const file = path.join(change, 'tasks.md');
  await fs.writeFile(file, '- [ ] implement\n');
  const first = await snapshot();
  gitExec('add', '-A');
  gitExec('commit', '-m', 'baseline');
  expect(await snapshot()).toBe(first);
  await fs.writeFile(file, '- [x] implement\n');
  expect(await snapshot()).toBe(first);
  await fs.writeFile(path.join(root, 'input.txt'), 'changed');
  expect(await snapshot()).not.toBe(first);
});

it('restricts environment only when declared and stores digests, not secrets', async () => {
  await writePolicy({ version: 1, env: ['COMET_TEST_REQUIRED'] });
  vi.stubEnv('COMET_TEST_REQUIRED', 'secret-one');
  vi.stubEnv('COMET_TEST_IRRELEVANT', 'one');
  const policy = await readCheckPolicy(root, identity);
  const environment = () => checkEnvironmentFingerprint([process.execPath], root, policy);
  const first = await environment();
  vi.stubEnv('COMET_TEST_IRRELEVANT', 'two');
  expect(await environment()).toBe(first);
  vi.stubEnv('COMET_TEST_REQUIRED', 'secret-two');
  expect(await environment()).not.toBe(first);
  expect(first).toMatch(/^[a-f0-9]{64}$/);
});

it('binds no environment variable without a declaration; legacy evidence keeps full binding', async () => {
  vi.stubEnv('COMET_TEST_IRRELEVANT', 'one');
  const current = async () =>
    checkEnvironmentFingerprint([process.execPath], root, await readCheckPolicy(root));
  const first = await current();
  vi.stubEnv('COMET_TEST_IRRELEVANT', 'two');
  expect(await current()).toBe(first);
  const legacy = async () =>
    checkEnvironmentFingerprint(
      [process.execPath],
      root,
      await readCheckPolicy(root, undefined, true),
      true,
    );
  const legacyFirst = await legacy();
